steps.command:
cat > /tmp/sshtest.exp <<'EOF'
set timeout 25
log_user 0
spawn ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no -p 2222 root@127.0.0.1
expect {
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)permission denied" { puts "RESULT: AUTH_FAILED"; exit 1 }
  -re "# $" {
    send "echo SSH_LOGIN_OK; id; uname -a; echo SSH_TEST_END\r"
    expect "SSH_TEST_END"
    puts "RESULT: SUCCESS"
    exit 0
  }
  timeout { puts "RESULT: TIMEOUT"; exit 1 }
}
EOF
expect -f /tmp/sshtest.exp 2>&1 | tail -20

cat > /tmp/sshtest2.exp <<'EOF'
set timeout 40
log_user 1
spawn ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no -o ConnectTimeout=10 -p 2222 root@127.0.0.1
expect {
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)permission denied" { puts "\nRESULT: AUTH_FAILED"; exit 1 }
  -re "# " {
    send "echo SSH_LOGIN_OK; id; echo SSH_TEST_END\r"
    expect "SSH_TEST_END"
    puts "\nRESULT: SUCCESS"
    exit 0
  }
  timeout { puts "\nRESULT: TIMEOUT"; exit 1 }
}
EOF
expect -f /tmp/sshtest2.exp 2>&1 | tail -30

getent hosts localhost; echo "---"; cat > /tmp/sshexact.exp <<'EOF'
set timeout 45
log_user 1
spawn ssh -p 2222 root@localhost
expect {
  -re "(?i)yes/no" { send "yes\r"; exp_continue }
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)permission denied" { puts "\nRESULT: AUTH_FAILED"; exit 1 }
  -re "# " {
    send "echo LOGIN_SUCCESS; whoami; hostname; echo TEST_DONE\r"
    expect "TEST_DONE"
    sendslow "exit\r"
    puts "\nRESULT: SUCCESS"
    exit 0
  }
  timeout { puts "\nRESULT: TIMEOUT"; exit 1 }
}
EOF
expect -f /tmp/sshexact.exp 2>&1 | tail -25

cat > /tmp/sshfinal.exp <<'EOF'
set timeout 30
log_user 0
spawn ssh -o PreferredAuthentications=password -o PubkeyAuthentication=no -p 2222 root@localhost
expect {
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)permission denied" { puts "RESULT: AUTH_FAILED"; exit 1 }
  -re "# " {
    send "printf 'WHOAMI=%s HOST=%s\\n' \"$(whoami)\" \"$(hostname)\"; printf 'FINAL_OK\\n'\r"
    expect "FINAL_OK"
    puts "RESULT: SUCCESS"
    exit 0
  }
  timeout { puts "RESULT: TIMEOUT"; exit 1 }
}
EOF
expect -f /tmp/sshfinal.exp 2>&1 | tail -5
