echo "=== tmux ==="; tmux ls 2>&1
echo "=== guest net ==="; tmux send-keys -t vm C-c 2>/dev/null; sleep 1; tmux send-keys -t vm -l "printf 'sshd: '; pgrep -c sshd; netstat -lnt | grep ':22 '; echo STATE_OK"; tmux send-keys -t vm Enter; for i in $(seq 1 15); do grep -aq "STATE_OK" /tmp/pane.raw && break; sleep 1; done; tail -c 350 /tmp/pane.raw

cat > /tmp/sshfinal2.exp <<'EOF'
